import {createWorkspace,demoWorkspace,addDeck,addCards,editCard,setStatus,recordAttempt,dueCards,summary,draftFromText,parseBackup,encodeBackup} from './core.js';
import {readWorkspace,saveWorkspace,restoreWorkspace,STORAGE_KEY,RECOVERY_KEY} from './storage.js';
import {excerptSegments} from './review-format.js';
import {teacherDraftKey,stabilizeDraftWorkspace,clearDraftWorkspace,prepareTeacherDraft,hasVolatileDrafts,formDraftIsVolatile,readFormDraft,writeFormDraft,clearFormDraft,readPractice,writePractice} from './work-in-progress.js';

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when = value => new Intl.DateTimeFormat('ru-KZ',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
const initial = readWorkspace();
let appearance='auto';
try{const saved=localStorage.getItem('sabaqloop.appearance');if(['light','dark'].includes(saved))appearance=saved;}catch{}
if(appearance!=='auto')document.documentElement.dataset.theme=appearance;
const temporaryStorage={getItem:key=>sessionStorage.getItem(key),setItem:(key,value)=>sessionStorage.setItem(key,value),removeItem:key=>sessionStorage.removeItem(key)};
let state=stabilizeDraftWorkspace(temporaryStorage,initial.state,initial.raw), rawRecovery=initial.raw, storageError=initial.error, observedRaw=initial.raw;
const resumed=readPractice(temporaryStorage,state);
let draftAtRisk=false, practiceStored=true;
let route='practice', deckId='', statusFilter='all', bankQuery='', selectedCardId='', bankControlsOpen=false, creating='', editing=null, session=resumed.session, pendingBackup=null, pendingRestoreRaw, importRead=0;
const notice = (message,error=false) => {$('#notice').textContent=message;$('#notice').classList.toggle('error',error);};
function clearImport(){pendingBackup=null;pendingRestoreRaw=undefined;importRead++;}
function persist(next){state=saveWorkspace(next,state.revision);observedRaw=JSON.stringify(state);clearDraftWorkspace(temporaryStorage);clearImport();}
function execute(fn){try{fn();}catch(e){notice(e.message,true);$('#notice').scrollIntoView({block:'nearest'});}}
function focusMain(){ $('#main').focus({preventScroll:true}); }
function sourceHtml(s){return `<div class="source"><strong>Источник: ${esc(s.title)}</strong>${s.url?` · <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Открыть</a>`:''}<blockquote>${esc(s.excerpt)}</blockquote></div>`;}
function deckSelect(){return `<div class="filter"><label for="deck-filter">Набор заданий</label><select id="deck-filter"><option value="">Все наборы</option>${state.decks.map(d=>`<option value="${esc(d.id)}" ${d.id===deckId?'selected':''}>${esc(d.title)}</option>`).join('')}</select></div>`;}
function head(title,lead,filter=true){return `<div class="page-head"><div><h1>${title}</h1><p class="lead">${lead}</p></div>${filter&&state.decks.length?deckSelect():''}</div>`;}
function sampleButton(){return `<button type="button" data-action="demo">Попробовать учебный пример</button>`;}
function empty(){return `<div class="empty"><h2>Первый круг практики начинается здесь</h2><p class="muted">Попробуйте три оригинальных задания по английскому или создайте свой набор. Вопрос, объяснение и источник остаются рядом.</p><div class="flow">${sampleButton()}<a class="button secondary" href="#bank">Создать свой набор</a></div><p class="note">Учебный пример — демонстрация возможностей. Это не официальный IELTS-тест.</p></div>`;}
function practice(){
  const all=state.cards.filter(c=>c.status==='approved'&&(!deckId||c.deckId===deckId));
  const due=dueCards(state,undefined,deckId||null), counts=summary(state);
  return head(session?'Круг практики':'Продолжим с того, что важно',session?'Ответ, объяснение и точный источник — один шаг за другим.':'Выберите материал. Проверенные задания готовы к практике, ошибки — к повторению.')+`<div class="workspace ${session?'practice-focus':''}"><div class="work-area">${session?practiceSession():!state.decks.length?empty():`<div class="practice-start"><h2>Ваша следующая практика</h2><div class="practice-actions"><div><p class="practice-quantity">${all.length}<span>проверенных заданий</span></p><button data-action="start" ${all.length?'':'disabled'}>Начать практику</button></div><div><p class="practice-quantity">${due.length}<span>к повторению сейчас</span></p><button class="secondary" data-action="review" ${due.length?'':'disabled'}>Разобрать ошибки</button></div></div>${!all.length?'<p class="note">В банке есть материал для проверки. Одобрите задание, чтобы открыть его для практики.</p><a class="button secondary" href="#bank">Проверить задания</a>':''}</div><section class="section"><h2>Последние попытки</h2>${historyHtml()}</section>`}</div><aside class="aside">${session?sessionIndex():`<section><h2>Материалы в тетради</h2><ul class="notebook-decks">${state.decks.map(d=>{const n=state.cards.filter(c=>c.deckId===d.id);return `<li><strong>${esc(d.title)}</strong><span>${n.filter(c=>c.status==='approved').length} в практике · ${n.filter(c=>c.status==='draft').length} на проверке</span></li>`;}).join('')||'<li>Ваш первый набор появится после добавления материала.</li>'}</ul><a class="button secondary" href="#bank">К материалу и заданиям</a></section><section><h2>История остаётся точной</h2><p>Каждая попытка сохраняет ту версию вопроса и источника, на которую вы ответили.</p><dl class="stats"><dt>Ответов в этой копии</dt><dd>${counts.attempts}</dd><dt>Доступно к повторению</dt><dd>${counts.due}</dd></dl></section>`}</aside></div>`;
}
function sessionIndex(){return `<section><h2>Этот круг</h2><ol class="session-index">${session.ids.map((id,index)=>`<li ${index===session.index?'aria-current="step"':''}><span>${String(index+1).padStart(2,'0')}</span><div><p>${esc(state.cards.find(c=>c.id===id)?.prompt)}</p><small>${index<session.attemptIds.length?'Ответ сохранён':index===session.index?'Сейчас':'Далее'}</small></div></li>`).join('')}</ol><p class="small">${practiceStored?(session.index>=session.ids.length?'Итог сохранён в этой вкладке. Кнопка «К практике» вернёт к материалам.':'Круг сохраняется в этой вкладке. После перезагрузки можно продолжить. Кнопка «Закончить» завершает его.'):'Браузер не разрешил сохранить положение в круге. После перезагрузки начните новый круг; записанные ответы останутся в истории.'}</p></section>`;}
function historyHtml(){
  const attempts=state.attempts.filter(a=>!deckId||a.snapshot.deckId===deckId).slice(-5).reverse();
  if(!attempts.length)return '<p class="small">Пока нет ответов. После практики здесь появится история с той версией задания, на которую вы отвечали.</p>';
  return `<ul class="history">${attempts.map(a=>`<li><div class="item-meta"><span class="badge ${a.correct?'':'draft'}">${a.correct?'Верно':'Нужно повторить'}</span><time datetime="${esc(a.at)}">${when(a.at)}</time><span class="small">Версия ${a.version}</span></div><p>${esc(a.snapshot.prompt)}</p><p class="small">Ваш ответ: <strong>${esc(a.answer)||'Ответ не введён'}</strong></p><details><summary>Ответ и источник этой версии</summary><p>Правильный ответ: <strong>${esc(a.snapshot.answer)}</strong></p><p>${esc(a.snapshot.explanation)}</p>${sourceHtml(a.snapshot.source)}</details></li>`).join('')}</ul>`;
}
function practiceSession(){
  if(session.index>=session.ids.length){
    return `<h2>Круг завершён</h2><p class="result-line">Верных ответов: <strong>${session.correct} из ${session.ids.length}</strong>.</p><p class="muted">Неверные ответы доступны к повторению сразу. Это результат этого круга, а не оценка уровня.</p><div class="flow section"><button data-action="finish">К практике</button><button class="secondary" data-action="review" ${dueCards(state,undefined,deckId||null).length?'':'disabled'}>Разобрать ошибки ещё раз</button></div>`;
  }
  const c=state.cards.find(c=>c.id===session.ids[session.index]);
  if(!c||c.status!=='approved') {session=null;return '<h2>Набор изменился</h2><p>Начните практику заново по актуальным заданиям.</p><button data-action="finish">Вернуться</button>';}
  const last=session.feedback, review=state.reviews[c.id];
  return `<div class="question-progress"><span>${session.mode==='review'?'Повторение':'Практика'} · ${session.index+1} из ${session.ids.length}</span><button class="quiet" data-action="finish">Закончить</button></div><progress value="${session.index}" max="${session.ids.length}" aria-label="Пройдено заданий"></progress><p class="question">${esc(c.prompt)}</p>${last?`<div class="feedback ${last.correct?'':'wrong'}" role="status"><h2>${last.correct?'Верно. Двигаемся дальше.':'Сохраним для повторения'}</h2><p>Ваш ответ: <strong>${esc(last.answer)||'Ответ не введён'}</strong></p>${!last.correct?`<p>Правильный ответ: <span class="answer-value">${esc(c.answer)}</span></p>`:''}<p>${esc(c.explanation)||'Преподаватель пока не добавил объяснение.'}</p>${sourceHtml(c.source)}<p class="small section">Следующее повторение: ${last.correct?when(review.dueAt):'доступно сейчас'}.</p></div><button data-action="next">${session.index+1===session.ids.length?'Завершить круг':'Следующее задание'}</button>`:`<form id="answer-form"><fieldset><legend>${c.type==='single'?'Выберите один ответ':'Введите ответ'}</legend>${c.type==='single'?c.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${esc(o)}" required><span>${esc(o)}</span></label>`).join(''):`<div class="field"><label class="small" for="answer">Слово или короткая фраза</label><input id="answer" name="answer" maxlength="2000" autocomplete="off" required><span class="hint">Проверяется точный ответ с учётом вариантов, добавленных преподавателем.</span></div>`}</fieldset><button type="submit">Проверить ответ</button></form>`}`;
}
function bank(){
  const needle=bankQuery.trim().toLocaleLowerCase('ru');
  const list=state.cards.filter(c=>(!deckId||c.deckId===deckId)&&(statusFilter==='all'||c.status===statusFilter)&&(!needle||[c.prompt,c.answer,c.source.title,c.source.excerpt].join(' ').toLocaleLowerCase('ru').includes(needle)));
  const total=state.cards.filter(c=>!deckId||c.deckId===deckId).length;
  const selected=list.find(c=>c.id===selectedCardId)||list[0];
  selectedCardId=selected?.id||'';
  const deck=state.decks.find(d=>d.id===deckId);
  return `<div class="editorial-bank"><aside class="question-index" aria-label="Указатель заданий"><div class="index-heading"><h1>Банк заданий</h1><p>${esc(deck?.title||(state.decks.length===1?state.decks[0].title:'Все наборы'))}</p></div><ol id="bank-results" class="question-list">${list.map((c,i)=>`<li><button class="question-link" data-action="select-card" data-id="${esc(c.id)}" ${c.id===selectedCardId?'aria-current="true"':''}><span class="question-number">${String(i+1).padStart(2,'0')}</span><span class="question-index-copy"><span>${esc(c.prompt)}</span><span class="question-status ${c.status}">${statusName(c.status)}</span></span></button></li>`).join('')}</ol><details id="bank-controls" class="bank-controls" ${bankControlsOpen||!state.decks.length?'open':''}><summary>Поиск и управление набором</summary>${state.decks.length?`${deckSelect()}<div class="field"><label for="bank-search">Найти задание или источник</label><input type="search" id="bank-search" value="${esc(bankQuery)}" placeholder="Вопрос, ответ, источник" aria-controls="bank-results" autocomplete="off"></div><div class="field"><label for="status-filter">Какие задания показать</label><select id="status-filter"><option value="all" ${statusFilter==='all'?'selected':''}>Все статусы</option><option value="draft" ${statusFilter==='draft'?'selected':''}>Нужна проверка</option><option value="approved" ${statusFilter==='approved'?'selected':''}>В практике</option><option value="archived" ${statusFilter==='archived'?'selected':''}>В архиве</option></select></div><p class="small" role="status">Найдено: ${list.length} из ${total}</p>`:''}<div class="composer-actions"><button class="quiet" data-action="compose-deck">Новый набор</button>${state.decks.length?`<button class="quiet" data-action="compose-material">Из материала</button><button class="quiet" data-action="compose-card">Добавить вручную</button>`:''}</div></details><p class="index-footnote">Сохраняется в этом браузере.<br>Экспортируйте копию перед сменой устройства.</p></aside><section class="reading-desk" aria-label="Проверка выбранного задания">${editing?`<div class="edit-sheet">${cardForm(state.cards.find(c=>c.id===editing))}<p class="note">Новая версия снова потребует проверки. Прежние попытки сохранят исходный текст.</p></div>`:creating?composerHtml():selected?reviewCard(selected,list.indexOf(selected)+1,list.length):`<div class="reading-empty"><p class="eyebrow">Материал · вопрос · практика</p><h2>${state.decks.length?'По этим условиям заданий нет':'Ваш материал — начало практики'}</h2><p>${state.decks.length?'Измените поиск или статус. Сохранённые задания остаются в банке.':'Создайте набор и добавьте свой учебный текст. Каждый вопрос сохранит точный фрагмент источника.'}</p><div class="flow section">${state.decks.length?'<button class="secondary" data-action="clear-search">Сбросить поиск и статус</button>':sampleButton()}</div></div>`}</section></div>`;
}
function statusName(status){return {draft:'Нужна проверка',approved:'В практике',archived:'В архиве'}[status];}
function excerptHtml(c){
  // Highlight only a literal source sentence containing the authored answer.
  // The entire exact excerpt stays readable; no generated source or explanation.
  const [before,match,after]=excerptSegments(c.source.excerpt,c.answer);
  return esc(before)+(match?`<mark>${esc(match)}</mark>`:'')+esc(after);
}
function proofPrompt(prompt){const m=prompt.match(/^([^:]{1,30}:) (.+)$/s);return m?`<p class="prompt-instruction eyebrow">${esc(m[1])}</p><h2 class="proof-prompt">${esc(m[2])}</h2>`:`<h2 class="proof-prompt">${esc(prompt)}</h2>`;}
function reviewCard(c,index,total){
  const deck=state.decks.find(d=>d.id===c.deckId);
  return `<article class="source-review"><section class="source-feature" aria-label="Исходный материал"><div class="source-reading"><p class="eyebrow">Источник · точный фрагмент</p><blockquote class="source-display ${c.source.excerpt.length>220?'long-excerpt':''}" ${c.source.excerpt.length>220?'tabindex="0" aria-label="Исходный фрагмент, прокручивается"':''}>${excerptHtml(c)}</blockquote>${c.explanation?`<p class="source-comment">${esc(c.explanation)}</p>`:''}<p class="source-title">${esc(c.source.title)}${c.source.url?` · <a href="${esc(c.source.url)}" target="_blank" rel="noopener noreferrer">Открыть источник</a>`:''}</p></div>${c.explanation?`<aside class="margin-note"><img src="./assets/arrow-arc-left.svg" width="44" height="44" alt=""><p>Проверьте по фрагменту:<br>${esc(c.answer)}</p></aside>`:''}</section><section class="question-proof" aria-label="Ответ и проверка"><div class="proof-meta"><span class="eyebrow">Задание ${index} из ${total}</span><div class="item-meta"><span class="badge ${c.status}">${statusName(c.status)}</span><span>Версия ${c.version}</span><span>${esc(deck?.title)}</span></div></div>${proofPrompt(c.prompt)}<div class="answer-with-options"><div class="proof-answer"><h3 class="eyebrow">Правильный ответ</h3><p>${esc(c.answer)}</p>${c.aliases.length?`<p class="small">Допустимо: ${c.aliases.map(esc).join(', ')}</p>`:''}</div>${c.type==='single'?`<details class="answer-options"><summary>Варианты ответа (${c.options.length})</summary><ul>${c.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></details>`:''}</div><div class="source-quote"><p class="eyebrow">Источник (точная цитата)</p><blockquote>«${esc(c.source.excerpt)}»</blockquote></div><div class="review-actions">${c.status!=='approved'?`<button data-action="approve" data-id="${esc(c.id)}">Проверено, в практику</button>`:'<p class="approved-note">Проверено · доступно в практике</p>'}<button class="secondary" data-action="edit" data-id="${esc(c.id)}">Редактировать</button>${c.status!=='archived'?`<button class="quiet archive-action" data-action="archive" data-id="${esc(c.id)}">В архив</button>`:''}</div><p class="review-hint">${c.status==='draft'?'Перед одобрением проверьте ответ, однозначность вопроса и права на материал.':c.status==='archived'?'Задание в архиве. Вы можете снова разрешить практику после проверки.':'Правка создаст новую версию и вернёт задание на проверку.'}</p></section></article>`;
}
function composerHtml(){return `<div class="edit-sheet"><button class="quiet" data-action="cancel-create">Закрыть создание</button><div class="section">${creating==='deck'?deckForm(true):creating==='material'?`<h2>Черновики из вашего материала</h2><p class="note">Используйте собственный или разрешённый текст. Каждый черновик потребует проверки перед практикой.</p>${materialForm()}`:cardForm()}</div></div>`;}
function deckForm(force=false){return `<details ${force||!state.decks.length?'open':''}><summary>Новый набор</summary><form id="deck-form"><div class="field"><label for="deck-title">Название набора</label><input id="deck-title" name="title" required minlength="2" maxlength="180" placeholder="Например, English · Present Perfect"></div><div class="two-col"><div class="field"><label for="deck-language">Язык материала</label><select id="deck-language" name="language"><option value="ru">Русский</option><option value="kk">Қазақша</option><option value="en">English</option><option value="mixed">Несколько языков</option></select></div><div class="field"><label for="deck-description">Описание, необязательно</label><input id="deck-description" name="description" maxlength="1000"></div></div><button type="submit">Создать набор</button></form></details>`;}
function deckField(prefix="manual"){return `<div class="field"><label for="${prefix}-target-deck">В какой набор добавить</label><select id="${prefix}-target-deck" name="deckId" required>${state.decks.map(d=>`<option value="${esc(d.id)}" ${d.id===deckId?'selected':''}>${esc(d.title)}</option>`).join('')}</select></div>`;}
function materialForm(){return `<form id="material-form">${deckField("material")}<div class="field"><label for="material-title">Название источника</label><input id="material-title" name="title" required maxlength="300" placeholder="Например, мой конспект занятия"></div><div class="field"><label for="material-url">Ссылка, если материал опубликован</label><input id="material-url" name="url" type="url" maxlength="2000" placeholder="https://..."></div><div class="field"><label for="material-text">Ваш учебный материал</label><textarea id="material-text" name="material" rows="7" required minlength="30" maxlength="40000" placeholder="Вставьте связный текст. Используйте свой материал или материал с разрешением на переработку."></textarea><span class="hint">До 40 000 символов. Текст не отправляется на сервер. Получится до 8 черновиков.</span></div><button type="submit">Создать черновики</button></form>`;}
function cardForm(c){return `<form id="card-form" data-card="${esc(c?.id||'')}"><h2>${c?'Редактирование задания':'Своё задание'}</h2>${!c?deckField():''}<div class="field"><label for="card-prompt">Вопрос</label><textarea id="card-prompt" name="prompt" required minlength="4" maxlength="2000">${esc(c?.prompt||'')}</textarea></div><div class="two-col"><div class="field"><label for="card-type">Тип ответа</label><select id="card-type" name="type"><option value="short" ${c?.type!=='single'?'selected':''}>Короткий ответ</option><option value="single" ${c?.type==='single'?'selected':''}>Один из вариантов</option></select></div><div class="field"><label for="card-answer">Правильный ответ</label><input id="card-answer" name="answer" required maxlength="500" value="${esc(c?.answer||'')}"></div></div><div class="field"><label for="card-options">Варианты для выбора, каждый с новой строки</label><textarea id="card-options" name="options" rows="3" maxlength="3100">${esc(c?.options.join('\n')||'')}</textarea><span class="hint">Для выбора: 2–6 разных вариантов, один точно совпадает с правильным ответом. Для короткого ответа оставьте пустым.</span></div><div class="field"><label for="card-aliases">Допустимые варианты короткого ответа, каждый с новой строки</label><textarea id="card-aliases" name="aliases" rows="2" maxlength="3000">${esc(c?.aliases.join('\n')||'')}</textarea></div><div class="field"><label for="card-explanation">Объяснение</label><textarea id="card-explanation" name="explanation" maxlength="3000">${esc(c?.explanation||'')}</textarea></div><div class="field"><label for="card-source">Название источника</label><input id="card-source" name="sourceTitle" required maxlength="300" value="${esc(c?.source.title||'')}"></div><div class="field"><label for="card-url">Ссылка на источник, необязательно</label><input id="card-url" name="sourceUrl" type="url" value="${esc(c?.source.url||'')}"></div><div class="field"><label for="card-excerpt">Исходный фрагмент, подтверждающий ответ</label><textarea id="card-excerpt" name="excerpt" required maxlength="12000">${esc(c?.source.excerpt||'')}</textarea></div><div class="flow"><button type="submit">${c?'Сохранить новую версию':'Сохранить черновик'}</button>${c?'<button type="button" class="secondary" data-action="cancel-edit">Отмена</button>':''}</div></form>`;}
function dataPage(){const s=summary(state);return head('Ваш материал остаётся у вас','Задания и ответы сохраняются в локальном хранилище этого браузера.',false)+`<div class="workspace"><div class="work-area"><section class="appearance"><h2>Оформление</h2><div class="field section"><label for="appearance">Тема рабочей области</label><select id="appearance"><option value="auto" ${appearance==='auto'?'selected':''}>Как на устройстве</option><option value="light" ${appearance==='light'?'selected':''}>Светлая бумага</option><option value="dark" ${appearance==='dark'?'selected':''}>Тёмная бумага</option></select></div></section><hr class="divider"><h2>Резервная копия</h2><p class="muted">Файл содержит наборы, источники, историю ответов и расписание. Сохраните его перед очисткой браузера или переносом на другое устройство.</p><dl class="stats"><dt>Наборов</dt><dd>${s.decks}</dd><dt>Всего заданий</dt><dd>${state.cards.length}</dd><dt>Ответов</dt><dd>${s.attempts}</dd></dl><div class="flow"><button data-action="export">Скачать JSON-копию</button><button class="secondary" data-action="recovery">Скачать предыдущую копию</button><button class="secondary" data-action="reload">Обновить данные</button></div><hr class="divider"><h2>Восстановить из файла</h2><p class="small">Сначала проверим файл и покажем содержимое. Замена произойдёт только после вашего подтверждения. Текущая копия сохранится отдельно для восстановления.</p><div class="field section"><label for="backup-file">JSON-файл SabaqLoop, до 5 МБ</label><input id="backup-file" type="file" accept="application/json,.json"></div>${pendingBackup?`<div class="data-preview"><h3>Файл прочитан. Проверьте замену.</h3><p>Наборов: ${pendingBackup.decks.length}; заданий: ${pendingBackup.cards.length}; ответов: ${pendingBackup.attempts.length}.</p><div class="flow section"><button data-action="import">Заменить локальные данные</button><button class="secondary" data-action="cancel-import">Отмена</button></div></div>`:''}<hr class="divider"><h2>Учебный пример</h2><p class="small">Добавить отдельный набор из трёх оригинальных заданий по английскому. Ваши наборы и ответы сохранятся.</p><div class="section">${sampleButton()}</div></div><aside class="aside"><section><h2>Что здесь хранится</h2><p>Одна рабочая область на браузер. Данные не синхронизируются с другим устройством и не разделены паролями.</p><p class="note">Не используйте эту версию для оценок класса, персональных данных учеников или закрытых документов.</p></section><section><h2>Нет фоновой отправки</h2><p>Сервис не вызывает AI API, не содержит аналитики и не отправляет материал на сервер. Внешняя ссылка на источник открывается по вашему нажатию.</p></section></aside></div>`;}
function recoveryPage(){return head('Сохранённая копия требует внимания','Данные не были сброшены автоматически.',false)+`<div class="work-area"><p role="alert">${esc(storageError)}</p><div class="flow section"><button data-action="export-raw" ${rawRecovery?'':'disabled'}>Скачать исходную копию</button><button class="secondary" data-action="reload">Обновить данные</button></div><div class="field section"><label for="backup-file">Или выберите исправную JSON-копию до 5 МБ</label><input id="backup-file" type="file" accept="application/json,.json"></div>${pendingBackup?`<div class="data-preview"><p>Прочитано наборов: ${pendingBackup.decks.length}; заданий: ${pendingBackup.cards.length}.</p><button data-action="import">Восстановить проверенную копию</button></div>`:''}</div>`;}
function prepareTeacherDrafts(){
  if(!state)return;
  for(const form of document.querySelectorAll('#deck-form,#material-form,#card-form')){
    const card=editing?state.cards.find(c=>c.id===editing):null;
    form.dataset.draftKey=teacherDraftKey(state.workspaceId,form.id,card);
    const draft=readFormDraft(temporaryStorage,form.dataset.draftKey);
    const restored=draft?prepareTeacherDraft(draft,state.decks):null;
    if(restored?.missingDeck){
      const target=form.elements.namedItem('deckId');
      if(target)target.prepend(new Option('Исходный набор недоступен — выберите набор',''));
    }
    if(restored)for(const field of form.elements){if(field.name&&Object.hasOwn(restored.fields,field.name)&&!field.disabled&&!field.readOnly){if(field.tagName!=='SELECT'||[...field.options].some(o=>o.value===restored.fields[field.name]))field.value=restored.fields[field.name];}}
    const status=document.createElement('p');status.className='draft-state';status.setAttribute('role','status');
    status.textContent=draft?(formDraftIsVolatile(temporaryStorage,form.dataset.draftKey)?'Текст восстановлен из памяти открытой страницы. Перезагрузка или закрытие страницы потеряет этот черновик; скопируйте его отдельно.':'Текст формы восстановлен из этой вкладки. Он ещё не сохранён как задание.'):'Текст формы автоматически сохраняется в этой вкладке до отправки.';
    if(restored?.missingDeck)status.textContent+=' Исходный набор недоступен. Текст сохранён; перед отправкой явно выберите набор.';
    else if(restored?.fields.deckId){const target=state.decks.find(deck=>deck.id===restored.fields.deckId);if(target)status.textContent+=` Набор черновика: «${target.title}».`;}
    form.prepend(status);
  }
  draftAtRisk=hasVolatileDrafts(temporaryStorage);
}
function saveTeacherDraft(form){
  if(!form?.dataset.draftKey)return;
  const saved=writeFormDraft(temporaryStorage,form.dataset.draftKey,Object.fromEntries(new FormData(form)));
  draftAtRisk=hasVolatileDrafts(temporaryStorage);
  const status=form.querySelector('.draft-state');
  if(status)status.textContent=saved?'Черновик формы сохранён в этой вкладке. Для добавления в набор нажмите кнопку сохранения.':'Черновик сохранён только в памяти открытой страницы. Можно переключать разделы, но перед перезагрузкой или закрытием скопируйте текст отдельно.';
}
function render(){practiceStored=writePractice(temporaryStorage,session,state);const controls=$('#bank-controls'),rail=$('#bank-results'),railScroll=rail?.scrollLeft||0,previousSelection=rail?.querySelector('[aria-current]')?.dataset.id;if(controls)bankControlsOpen=controls.open;route=['practice','bank','data'].includes(location.hash.slice(1))?location.hash.slice(1):'practice';document.body.dataset.page=route;document.querySelectorAll('[data-route]').forEach(a=>{if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=!state?recoveryPage():route==='bank'?bank():route==='data'?dataPage():practice();const nextRail=$('#bank-results');if(nextRail){nextRail.scrollLeft=railScroll;if(matchMedia('(max-width:620px)').matches&&previousSelection!==selectedCardId){const current=nextRail.querySelector('[aria-current]');if(current)nextRail.scrollLeft=current.offsetLeft-nextRail.offsetLeft;}}prepareTeacherDrafts();}
function download(content,name){const a=document.createElement('a'), url=URL.createObjectURL(new Blob([content],{type:'application/json;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function start(mode){const cards=mode==='review'?dueCards(state,undefined,deckId||null):state.cards.filter(c=>c.status==='approved'&&(!deckId||c.deckId===deckId));if(!cards.length){notice('По этому набору пока нет заданий для выбранного режима.');return;}session={ids:cards.map(c=>c.id),index:0,correct:0,mode,feedback:null,attemptIds:[]};render();focusMain();}
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-action]');if(!b)return;event.preventDefault();
 execute(()=>{const action=b.dataset.action, cid=b.dataset.id;notice('');
  if(action==='clear-search'){bankQuery='';statusFilter='all';}
  if(action==='select-card'){selectedCardId=cid;editing=null;creating='';}
  if(action.startsWith('compose-')){creating=action.slice(8);editing=null;}
  if(action==='cancel-create')creating='';
  if(action==='demo'){const demo=demoWorkspace();let next=addDeck(state,demo.decks[0]);next=addCards(next,demo.cards);persist(next);deckId=demo.decks[0].id;session=null;notice('Добавлен учебный пример: три оригинальных задания.');if(route==='practice'){start('practice');return;}}
  if(action==='start'){start('practice');return;}if(action==='review'){start('review');return;}
  if(action==='next'){session.index++;session.feedback=null;}
  if(action==='finish')session=null;
  if(action==='approve'){persist(setStatus(state,cid,'approved'));notice('Задание разрешено для практики.');}
  if(action==='archive'){persist(setStatus(state,cid,'archived'));notice('Задание перенесено в архив. История ответов сохранена.');}
  if(action==='edit'){editing=cid;creating='';}
  if(action==='cancel-edit')editing=null;
  if(action==='export'){download(encodeBackup(state),'sabaqloop-backup.json');notice('Копия подготовлена для скачивания.');return;}
  if(action==='export-raw'){download(rawRecovery,'sabaqloop-original-recovery.json');return;}
  if(action==='recovery'){const old=localStorage.getItem(RECOVERY_KEY);if(!old)throw new Error('Предыдущей копии пока нет. Она создаётся перед восстановлением из файла.');download(old,'sabaqloop-previous-copy.json');return;}
  if(action==='cancel-import')clearImport();
  if(action==='import'){if(!pendingBackup||pendingRestoreRaw===undefined)throw new Error('Выберите JSON-копию и проверьте её заново.');state=restoreWorkspace(pendingBackup,localStorage,pendingRestoreRaw);observedRaw=JSON.stringify(state);storageError=null;clearDraftWorkspace(temporaryStorage);clearImport();editing=null;session=null;deckId='';notice('Проверенная копия восстановлена. Предыдущая сохранена отдельно.');}
  if(action==='reload'){const loaded=readWorkspace();state=stabilizeDraftWorkspace(temporaryStorage,loaded.state,loaded.raw);storageError=loaded.error;rawRecovery=loaded.raw;observedRaw=loaded.raw;clearImport();session=null;editing=null;notice(loaded.error||'Данные обновлены.',!!loaded.error);}
  render();if(['next','finish','edit','cancel-edit','compose-card','compose-material','compose-deck','cancel-create'].includes(action))focusMain();if(action==='select-card'){$('.reading-desk').setAttribute('tabindex','-1');$('.reading-desk').focus({preventScroll:true});}
 });
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!['deck-form','material-form','card-form','answer-form'].includes(form.id))return;event.preventDefault();
 execute(()=>{const f=Object.fromEntries(new FormData(form));notice('');
  if(form.id==='deck-form'){const next=addDeck(state,f);persist(next);deckId=next.decks.at(-1).id;creating='';notice('Набор создан. Добавьте материал или своё задание.');}
  if(form.id==='material-form'){const cards=draftFromText(f);persist(addCards(state,cards));deckId=f.deckId;statusFilter='draft';bankQuery='';selectedCardId=cards[0]?.id||'';creating='';notice(`Создано черновиков: ${cards.length}. Проверьте каждый ответ и источник перед практикой.`);}
  if(form.id==='card-form'){const input={...f,options:f.options.split('\n').map(s=>s.trim()).filter(Boolean),aliases:f.aliases.split('\n').map(s=>s.trim()).filter(Boolean),source:{title:f.sourceTitle,url:f.sourceUrl,excerpt:f.excerpt}};if(form.dataset.card){persist(editCard(state,form.dataset.card,input));selectedCardId=form.dataset.card;editing=null;}else{persist(addCards(state,[input]));selectedCardId=state.cards.at(-1).id;deckId=f.deckId;}statusFilter='draft';bankQuery='';creating='';notice('Сохранено как черновик. Проверьте задание, затем разрешите практику.');}
  if(form.id==='answer-form'){if(!session||session.feedback)return;const cid=session.ids[session.index],next=recordAttempt(state,{cardId:cid,answer:f.answer,mode:session.mode});persist(next);const a=next.attempts.at(-1);session.attemptIds.push(a.id);session.feedback={correct:a.correct,answer:a.answer};if(a.correct)session.correct++;}
  if(form.dataset.draftKey){clearFormDraft(temporaryStorage,form.dataset.draftKey);draftAtRisk=hasVolatileDrafts(temporaryStorage);}
  render();focusMain();
 });
});
document.addEventListener('input',event=>{
 saveTeacherDraft(event.target.closest('form'));
 if(event.target.id==='bank-search'){const start=event.target.selectionStart,end=event.target.selectionEnd;bankQuery=event.target.value;render();const search=$('#bank-search');search.focus({preventScroll:true});search.setSelectionRange(start,end);}
});
document.addEventListener('change',event=>{
 saveTeacherDraft(event.target.closest('form'));
 if(event.target.id==='appearance'){appearance=event.target.value;if(appearance==='auto')delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=appearance;try{localStorage.setItem('sabaqloop.appearance',appearance);}catch{notice('Тема изменена для этой вкладки. Сохранить настройку в браузере не удалось.',true);}}
 if(event.target.id==='deck-filter'){deckId=event.target.value;session=null;editing=null;render();}
 if(event.target.id==='status-filter'){statusFilter=event.target.value;render();}
 if(event.target.id==='backup-file'){
  const file=event.target.files[0];clearImport();const readId=importRead,previewRaw=observedRaw;render();if(!file)return;
  if(file.size>5_000_000){notice('Файл больше 5 МБ. Текущие данные не изменены.',true);return;}
  notice('Проверяем файл…');file.text().then(content=>{if(readId!==importRead)return;execute(()=>{pendingBackup=parseBackup(content);pendingRestoreRaw=previewRaw;notice('Файл проверен. Подтвердите замену ниже.');render();});}).catch(()=>{if(readId===importRead)notice('Не удалось прочитать файл. Выберите JSON-копию ещё раз.',true);});
 }
});
window.addEventListener('hashchange',()=>{session=null;editing=null;creating='';notice('');render();focusMain();});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY)notice('Данные изменились в другой вкладке. Сохраните введённый текст и обновите данные.',true);});
$('#today').textContent=new Intl.DateTimeFormat('ru-KZ',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Almaty'}).format(new Date());
window.addEventListener('beforeunload',event=>{if(draftAtRisk){event.preventDefault();event.returnValue='';}});
render();if(storageError)notice(storageError,true);else if(resumed.message)notice(resumed.message);
